#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <cstring>

using namespace std;

// 宏定义：快速4循环置换
#define CYCLE4(a,b,c,d) {char _t=s[a]; s[a]=s[d]; s[d]=s[c]; s[c]=s[b]; s[b]=_t;}

struct Cube {
    char s[54];
    
    // 按 U, D, L, R, F, B 顺序读取
    void read() {
        string faces[6];
        for (int i = 0; i < 6; ++i) cin >> faces[i];
        for (int i = 0; i < 9; ++i) {
            s[i]=faces[0][i]; s[9+i]=faces[1][i]; s[18+i]=faces[2][i];
            s[27+i]=faces[3][i]; s[36+i]=faces[4][i]; s[45+i]=faces[5][i];
        }
    }

    bool is_solved() const {
        for (int i = 0; i < 6; ++i) if(s[i*9]!=s[i*9+1] || s[i*9]!=s[i*9+8]) return false;
        return true;
    }

    // 6 种基本顺时针旋转
    void move(int m) {
        switch (m) {
            case 0: CYCLE4(0,2,8,6); CYCLE4(1,5,7,3); CYCLE4(36,27,45,18); CYCLE4(37,28,46,19); CYCLE4(38,29,47,20); break; // U
            case 1: CYCLE4(9,11,17,15); CYCLE4(10,14,16,12); CYCLE4(42,33,51,24); CYCLE4(43,34,52,25); CYCLE4(44,35,53,26); break; // D
            case 2: CYCLE4(18,20,26,24); CYCLE4(19,23,25,21); CYCLE4(0,36,9,53); CYCLE4(3,39,12,50); CYCLE4(6,42,15,47); break; // L
            case 3: CYCLE4(27,29,35,33); CYCLE4(28,32,34,30); CYCLE4(8,45,17,44); CYCLE4(5,48,14,41); CYCLE4(2,51,11-0+0,38); break; // R (修正: 11)
            case 4: CYCLE4(36,38,44,42); CYCLE4(37,41,43,39); CYCLE4(6,27,47,24); CYCLE4(7,30,46,23); CYCLE4(8,33,45,20); break; // F
            case 5: CYCLE4(45,47,53,51); CYCLE4(46,50,52,48); CYCLE4(2,18,53,35); CYCLE4(1,21,50,32); CYCLE4(0,24,47,29); break; // B
        }
    }
};

// 修正 R 的宏展开问题，重新内联
inline void apply_move(Cube& c, int m) {
    char* s = c.s;
    switch (m) {
        case 0: CYCLE4(0,2,8,6); CYCLE4(1,5,7,3); CYCLE4(36,27,45,18); CYCLE4(37,28,46,19); CYCLE4(38,29,47,20); break;
        case 1: CYCLE4(9,11,17,15); CYCLE4(10,14,16,12); CYCLE4(42,33,51,24); CYCLE4(43,34,52,25); CYCLE4(44,35,53,26); break;
        case 2: CYCLE4(18,20,26,24); CYCLE4(19,23,25,21); CYCLE4(0,36,9,53); CYCLE4(3,39,12,50); CYCLE4(6,42,15,47); break;
        case 3: CYCLE4(27,29,35,33); CYCLE4(28,32,34,30); CYCLE4(8,45,17,44); CYCLE4(5,48,14,41); CYCLE4(2,51,11,38); break;
        case 4: CYCLE4(36,38,44,42); CYCLE4(37,41,43,39); CYCLE4(6,27,47,24); CYCLE4(7,30,46,23); CYCLE4(8,33,45,20); break;
        case 5: CYCLE4(45,47,53,51); CYCLE4(46,50,52,48); CYCLE4(2,18,53,35); CYCLE4(1,21,50,32); CYCLE4(0,24,47,29); break;
    }
}

// 反向操作映射：U', D', L', R', F', B'
inline void apply_move_inv(Cube& c, int m) {
    apply_move(c, m); apply_move(c, m); apply_move(c, m);
}

const char MOVE_NAMES[] = {'U', 'D', 'L', 'R', 'F', 'B'};
// G0 子群允许的操作：U, D, R2, L2, F2, B2 (0, 1, 6, 7, 8, 9)
const int G1_MOVES[] = {0, 1, 6, 7, 8, 9};
const int CO_SIZE = 2187;   // 3^7 角块方向
const int EO_SIZE = 2048;   // 2^11 边块方向

int co_table[CO_SIZE]; // 角块方向剪枝表
int eo_table[EO_SIZE]; // 边块方向剪枝表

// 计算坐标的辅助表
int edge_perm_map[12];
int edge_orient_map[12];
int corner_perm_map[8];
int corner_orient_map[8];

void init_maps() {
    // 通过一次虚拟的乱序旋转，提取各块所在位置及方向对应关系
    // 这里采用直接映射标准魔方初始态的方式
    // 边块：UR, UF, UL, UB, DR, DF, DL, DB, FR, FL, BR, BL
    int ep[12] = {3, 5, 1, 7, 21, 23, 19, 25, 39, 41, 30, 48}; // 不需要太复杂，我们直接硬编码
    for(int i=0; i<12; ++i) { edge_perm_map[i] = i; edge_orient_map[i] = 0; }
    for(int i=0; i<8; ++i) { corner_perm_map[i] = i; corner_orient_map[i] = 0; }
}

// 获取角块方向坐标 (0 ~ 2186)
int get_co(const Cube& c) {
    int co = 0;
    // 硬编码8个角块的主副面索引，顺序：URF, UFL, ULB, UBR, DFR, DLF, DBL, DRB
    int corners[8][2] = {{8,36},{6,18},{0,45},{2,27},{38,44},{42,24},{51,26},{35,47}};
    for (int i = 0; i < 7; ++i) {
        char c1 = c.s[corners[i][0]];
        char c2 = c.s[corners[i][1]];
        int ori = 0;
        if (c1 == 'W' || c1 == 'Y') ori = (c2 == 'R' || c2 == 'O') ? 1 : 2;
        else if (c1 == 'R' || c1 == 'O') ori = (c2 == 'W' || c2 == 'Y') ? 2 : 1;
        co = co * 3 + ori;
    }
    return co;
}

// 获取边块方向坐标 (0 ~ 2047)
int get_eo(const Cube& c) {
    int eo = 0;
    // 硬编码12个边块的主副面索引
    int edges[12][2] = {{5,37},{7,28},{3,19},{1,46},{21,41},{23,32},{15,50},{17,25},{39,33},{48,30},{42,53},{24,47}};
    for (int i = 0; i < 11; ++i) {
        char c1 = c.s[edges[i][0]];
        char c2 = c.s[edges[i][1]];
        int ori = 0;
        if (c1 == 'W' || c1 == 'Y') ori = (c2 == 'R' || c2 == 'O') ? 1 : 0;
        else if (c1 == 'R' || c1 == 'O') ori = 0;
        else ori = 1;
        eo = eo * 2 + ori;
    }
    return eo;
}

// BFS 预计算剪枝表
void bfs_table(int* table, int size, int (*get_coord)(const Cube&)) {
    memset(table, -1, size * sizeof(int));
    Cube solved;
    // 初始化复原状态
    char faces[6] = {'W', 'Y', 'R', 'O', 'G', 'B'};
    for(int i=0; i<6; ++i) for(int j=0; j<9; ++j) solved.s[i*9+j] = faces[i];
    
    queue<pair<Cube, int>> q;
    q.push({solved, 0});
    table[get_coord(solved)] = 0;

    while (!q.empty()) {
        auto [cur, d] = q.front(); q.pop();
        if (d >= 7) continue; // 阶段一深度不超过7
        for (int m = 0; m < 6; ++m) {
            Cube next = cur;
            apply_move(next, m);
            int coord = get_coord(next);
            if (table[coord] == -1) {
                table[coord] = d + 1;
                q.push({next, d + 1});
            }
        }
    }
}

// 阶段一的 IDA* 搜索：消除角块和边块方向错误
vector<int> phase1_path;
bool phase1_dfs(Cube& c, int depth, int max_depth, int last_move) {
    if (get_co(c) == 0 && get_eo(c) == 0) return true;
    if (depth == max_depth) return false;
    
    int h = max(co_table[get_co(c)], eo_table[get_eo(c)]);
    if (depth + h > max_depth) return false; // 剪枝

    for (int i = 0; i < 6; ++i) {
        if (i == last_move) continue;
        if ((i ^ 1) == last_move && i > last_move) continue; // 互逆操作去重 (U/D, L/R, F/B)
        
        Cube next = c;
        apply_move(next, i);
        phase1_path.push_back(i);
        if (phase1_dfs(next, depth + 1, max_depth, i)) return true;
        phase1_path.pop_back();
    }
    return false;
}

// 阶段二的 IDA* 搜索：在 G1 子群内复原位置 (仅用 U, D, R2, L2, F2, B2)
// 由于阶段二最多18步，纯BFS状态可达百万，需进一步用位置剪枝。
// 为保证不TLE，这里使用双向BFS或限制深度DFS。我们简化处理，用深搜+强去重
vector<int> phase2_path;
bool phase2_dfs(Cube& c, int depth, int max_depth, int last_move) {
    if (c.is_solved()) return true;
    if (depth == max_depth) return false;

    for (int i = 0; i < 6; ++i) {
        int m = G1_MOVES[i];
        // 同轴去重
        if (m == last_move) continue;
        if ((m < 2 && last_move < 2 && m != last_move) && m > last_move) continue; 

        Cube next = c;
        if (m < 2) apply_move(next, m);
        else { apply_move(next, m-4); apply_move(next, m-4); } // 执行 180 度
        
        phase2_path.push_back(m);
        if (phase2_dfs(next, depth + 1, max_depth, m)) return true;
        phase2_path.pop_back();
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Cube cube;
    cube.read();
    if (cube.is_solved()) { cout << "0 \n"; return 0; }

    // 1. 预计算阶段一剪枝表
    bfs_table(co_table, CO_SIZE, get_co);
    bfs_table(eo_table, EO_SIZE, get_eo);

    // 2. 执行阶段一搜索
    vector<int> full_path;
    for (int d = 0; d <= 12; ++d) {
        phase1_path.clear();
        if (phase1_dfs(cube, 0, d, -1)) {
            full_path = phase1_path;
            break;
        }
    }

    // 将魔方转换到 G1 子群状态
    Cube c_g1 = cube;
    for (int m : full_path) apply_move(c_g1, m);

    // 3. 执行阶段二搜索
    for (int d = 0; d <= 18; ++d) {
        phase2_path.clear();
        if (phase2_dfs(c_g1, 0, d, -1)) {
            full_path.insert(full_path.end(), phase2_path.begin(), phase2_path.end());
            break;
        }
    }

    // 输出结果：将操作步骤展开为 U, D, R, L, F, B 的单步序列
    cout << full_path.size() << " ";
    for (int m : full_path) cout << MOVE_NAMES[m];
    cout << "\n";

    return 0;
}
